// 18-tap direct-form FIR, 8-bit samples, PIPELINED: products registered in
// stage 1, summed in stage 2 -> shorter register-to-register path, higher Fmax.
// Functionally identical to the reference up to a fixed extra latency.
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    reg  [15:0] p  [0:17];
    integer     i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) begin xs[i] <= 8'd0; p[i] <= 16'd0; end
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            p[0] <= 8'd2 * xs[0] + 3;
            p[1] <= 8'd4 * xs[1] + 6;
            p[2] <= 8'd6 * xs[2] + 9;
            p[3] <= 8'd8 * xs[3] + 12;
            p[4] <= 8'd10 * xs[4] + 15;
            p[5] <= 8'd12 * xs[5] + 18;
            p[6] <= 8'd14 * xs[6] + 21;
            p[7] <= 8'd16 * xs[7] + 24;
            p[8] <= 8'd18 * xs[8] + 27;
            p[9] <= 8'd20 * xs[9] + 30;
            p[10] <= 8'd22 * xs[10] + 33;
            p[11] <= 8'd24 * xs[11] + 36;
            p[12] <= 8'd26 * xs[12] + 39;
            p[13] <= 8'd28 * xs[13] + 42;
            p[14] <= 8'd30 * xs[14] + 45;
            p[15] <= 8'd32 * xs[15] + 48;
            p[16] <= 8'd34 * xs[16] + 51;
            p[17] <= 8'd36 * xs[17] + 54;
            y <= p[0] + p[1] + p[2] + p[3] + p[4] + p[5] + p[6] + p[7] + p[8] + p[9] + p[10] + p[11] + p[12] + p[13] + p[14] + p[15] + p[16] + p[17];
        end
    end
endmodule
